import{_ as a,a0 as d,w as p,s as u,ao as o,I as r,x as t,a1 as s,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"userdel 命令 - 从Linux系统中删除用户账户 | LCTT x X-CMD","titleTemplate":false,"description":"userdel 命令 - 从Linux系统中删除用户账户 | LCTT (201402) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"userdel 命令 - 从Linux系统中删除用户账户 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"userdel 命令 - 从Linux系统中删除用户账户 | LCTT (201402) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201402/userdel Command - Delete User Account from Linux system","title":"userdel 命令 - 从Linux系统中删除用户账户","tag":"201402","desc":""},"relativePath":"201402/userdel Command - Delete User Account from Linux system.md","filePath":"[post].md"}'),i={name:"201402/userdel Command - Delete User Account from Linux system.md"};function m(x,e,g,f,T,L){const n=d("Link");return p(),u("div",null,[e[20]||(e[20]=o(`<h1 id="userdel-命令-从linux系统中删除用户账户" tabindex="-1">userdel 命令 - 从Linux系统中删除用户账户 <a class="header-anchor" href="#userdel-命令-从linux系统中删除用户账户" aria-label="Permalink to “userdel 命令 - 从Linux系统中删除用户账户”">​</a></h1><p>在服务器上维护用户就是添加、修改以及删除用户。当一个用户出于某种原因不再需要登录系统时，我们需要删除此用户以避免安全漏洞。在Linux系统上，我们用 <strong>userdel</strong> 命令来删除一个用户。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/userdel-linux-command.jpg" alt=""></p><h3 id="userdel是什么" tabindex="-1">userdel是什么 <a class="header-anchor" href="#userdel是什么" aria-label="Permalink to “userdel是什么”">​</a></h3><p>userdel 是一个底层用于删除用户的工具。在 Debian 上，我们通常会使用 deluser 命令。userdel 会查询系统账户文件，例如 <strong>/etc/password</strong> 和 <strong>/etc/group</strong>。那么它会删除所有和用户名相关的条目。在我们删除它之前，用户名必须存在。</p><h3 id="如何使用userdel" tabindex="-1">如何使用userdel <a class="header-anchor" href="#如何使用userdel" aria-label="Permalink to “如何使用userdel”">​</a></h3><p>由于 userdel 会修改系统账户文件，那么我们<strong>需要root特权</strong>来运行它。不然我们会遇到一个报错信息“<em>只有root权限才能执行这项操作</em>”或者类似的信息。在我们得到特权后，我们可以通过输入 userdel 从你的控制台删除用户。下面是一个默认使用 userdel 的样例。</p><pre><code>$ sudo userdel pasadena
</code></pre><p>或者</p><pre><code># userdel pasadena
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/userdel_default.png" alt=""></p><p>正如你所见，我们不能没有root权限而删除用户 pasadena。当我们有权限时，系统不会给出错误信息，这意味着用户已经成功删除。</p><h3 id="完全删除用户家目录" tabindex="-1">完全删除用户家目录 <a class="header-anchor" href="#完全删除用户家目录" aria-label="Permalink to “完全删除用户家目录”">​</a></h3><p>不带选项使用 userdel，只会删除用户。用户的家目录将仍会在/home目录下。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/userdel_home_folder.png" alt=""></p><p>当我们进入/home目录时，我们仍旧可以看到ID 1002拥有 pasadena 文件夹。已创建的用户通常会有一个与用户名相同的组名。1002是 pasadena 用户名的 UID 和 pasadena 组名的 GID。</p><p>为了在删除用户时完全删除家目录，我们可以使用 <strong>-r</strong> 选项。这个选项同样会删除用户的邮件池，如果存在的话。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/userdel_r.png" alt=""></p><h3 id="强制删除一个用户" tabindex="-1">强制删除一个用户 <a class="header-anchor" href="#强制删除一个用户" aria-label="Permalink to “强制删除一个用户”">​</a></h3><p>userdel 提供了 <strong>-f</strong> 选项来强制删除用户。甚至当用户已经登入 Linux 系统时此选项仍旧生效。请看一下示例截图。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/userdel_f.png" alt=""></p>`,21)),r("p",null,[e[1]||(e[1]=t("截图的上面显示用户 pasadena 已经登录了系统。它被标记的进程",-1)),e[2]||(e[2]=r("strong",null,"6218",-1)),e[3]||(e[3]=t("是 SSHD 进程。而当我们用“",-1)),e[4]||(e[4]=r("strong",null,"userdel -f pasadena",-1)),e[5]||(e[5]=t("”只会显示已经登录的要被删除的用户信息。命令本身已经成功。如果我们使用",-1)),s(n,{href:"http://linoxide.com/linux-command/13-cat-command-examples/"},{default:l(()=>[...e[0]||(e[0]=[t("cat 命令",-1)])]),_:1}),e[6]||(e[6]=t("查看",-1)),e[7]||(e[7]=r("strong",null,"/etc/passwd",-1)),e[8]||(e[8]=t("的内容，我们看不到到用户 pasadena 存在了。他的家目录还存在但是所有者只能显示为数字ID。",-1))]),e[21]||(e[21]=o('<p>有一件事我们必须了解，带 <strong>-f</strong> 选项的 userdel <strong>不会断开</strong> 该用户已有的 SSH 链接。因此，即使用户已经不存在，但实际上仍是登录状态，并且是活跃用户。但是当用户登出后不可再登录，因为用户已经被删除。</p><p>因此<strong>所以这个选项使用起来有些危险</strong>，因为它会使你的系统进入不一致的状态。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>userdel 是一个 Linux 系统内部删除用户的工具。userdel同样是<strong>deluser</strong>命令的后端，这是一个用perl编写的删除用户的脚本。如往常一样，你可以输入<strong>man userdel</strong>来查看关于userdel命令的更多细节。</p><hr>',5)),r("p",null,[e[10]||(e[10]=t("via: ",-1)),s(n,{href:"http://linoxide.com/linux-command/linux-userdel-command/"},{default:l(()=>[...e[9]||(e[9]=[t("http://linoxide.com/linux-command/linux-userdel-command/",-1)])]),_:1})]),r("p",null,[e[13]||(e[13]=t("译者：",-1)),s(n,{href:"https://github.com/geekpi"},{default:l(()=>[...e[11]||(e[11]=[t("geekpi",-1)])]),_:1}),e[14]||(e[14]=t(" 校对：",-1)),s(n,{href:"https://github.com/carolinewuyan"},{default:l(()=>[...e[12]||(e[12]=[t("Caroline",-1)])]),_:1})]),r("p",null,[e[17]||(e[17]=t("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[15]||(e[15]=[t("LCTT",-1)])]),_:1}),e[18]||(e[18]=t(" 原创翻译，",-1)),s(n,{href:"http://linux.cn/"},{default:l(()=>[...e[16]||(e[16]=[t("Linux中国",-1)])]),_:1}),e[19]||(e[19]=t(" 荣誉推出",-1))])])}const b=a(i,[["render",m]]);export{D as __pageData,b as default};
